<?php
require __DIR__ . '/../config/database.php';require __DIR__ . '/../config/helpers.php';
$periode=trim((string)($_POST['periode']??$_GET['periode']??date('Y-m-d')));$d=DateTime::createFromFormat('Y-m-d',$periode);if(!$d||$d->format('Y-m-d')!==$periode)$periode=date('Y-m-d');
$ahpId=(int)($_POST['ahp_id']??$_GET['ahp_id']??0);$namaAcuan=trim((string)($_POST['nama_acuan']??$_GET['nama_acuan']??''));
$ahps=$pdo->query("SELECT id_simulasi,nama_simulasi,nama_acuan,periode,cr FROM simulasi WHERE status='draft' AND cr <= 0.1 AND source_ahp_id IS NULL ORDER BY id_simulasi DESC")->fetchAll();
if(!$ahpId&&$namaAcuan!==''){foreach($ahps as $x)if($x['nama_acuan']===$namaAcuan&&$x['periode']===$periode){$ahpId=(int)$x['id_simulasi'];break;}}
$selected=null;foreach($ahps as $x)if((int)$x['id_simulasi']===$ahpId){$selected=$x;break;}
$errors=[];$hasilHitung=[];$kriteria=[];$alternatif=[];
if($selected){$wb=$pdo->prepare('SELECT kode_kriteria,nama_kriteria,tipe_kriteria,bobot FROM ahp_bobot WHERE id_simulasi=? ORDER BY kode_kriteria');$wb->execute([$ahpId]);$weights=$wb->fetchAll();$kriteria=$weights;if(count($weights)!==6 || array_column($weights,'kode_kriteria')!==['C1','C2','C3','C4','C5','C6'])$errors[]='Hasil AHP ini tidak memiliki enam kriteria C1–C6 yang sesuai. Hitung ulang AHP setelah migrasi.';
 $pAlt=$selected['periode']?:$periode;$as=$pdo->prepare('SELECT * FROM alternatif WHERE periode=? ORDER BY nama');$as->execute([$pAlt]);$alternatif=$as->fetchAll();
 if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$chosen=$_POST['alternatif_ids']??[];if(!is_array($chosen))$chosen=[];$chosen=array_values(array_unique(array_filter(array_map('intval',$chosen))));if(count($chosen)<2)$errors[]='Pilih minimal dua alternatif untuk dibandingkan.';
  $map=[];foreach($alternatif as $a)$map[(int)$a['id_alternatif']]=$a;foreach($chosen as $id)if(!isset($map[$id]))$errors[]='Alternatif yang dipilih tidak termasuk periode AHP tersebut.';
  if(!$weights)$errors[]='Bobot AHP tidak ditemukan. Hitung AHP lagi setelah menjalankan migrasi.';
  if(!$errors){$ns=$pdo->prepare('SELECT k.kode,k.nama,k.tipe,n.nilai FROM nilai_alternatif n JOIN kriteria k ON k.id_kriteria=n.id_kriteria WHERE n.id_alternatif=?');$data=[];foreach($chosen as $id){$ns->execute([$id]);$rows=$ns->fetchAll();$vals=[];foreach($rows as $r)$vals[$r['kode']]=(float)$r['nilai'];foreach($weights as $k)if(!isset($vals[$k['kode_kriteria']])||$vals[$k['kode_kriteria']]<=0)$errors[]='Nilai '.$k['nama_kriteria'].' pada '.$map[$id]['nama'].' belum lengkap atau tidak positif.';$data[]=['alternatif'=>$map[$id],'nilai'=>$vals];}}
  if(!$errors){$sumW=array_sum(array_map(fn($w)=>(float)$w['bobot'],$weights));if($sumW<=0)$errors[]='Bobot AHP tidak valid.';else{foreach($data as $item){$logS=0;$kontribusi=[];foreach($weights as $k){$code=$k['kode_kriteria'];$x=$item['nilai'][$code];$w=(float)$k['bobot']/$sumW;$pow=strtolower($k['tipe_kriteria'])==='cost'?-$w:$w;$con=pow($x,$pow);$kontribusi[$code]=['kriteria'=>$k,'nilai'=>$x,'bobot'=>$w,'pangkat'=>$pow,'kontribusi'=>$con];$logS+=$pow*log($x);}$hasilHitung[]=['alternatif'=>$item['alternatif'],'nilai'=>$item['nilai'],'log_s'=>$logS,'kontribusi'=>$kontribusi];}$maxLog=max(array_column($hasilHitung,'log_s'));$total=0;foreach($hasilHitung as &$h){$h['s_rel']=exp($h['log_s']-$maxLog);$total+=$h['s_rel'];}unset($h);foreach($hasilHitung as &$h){$h['s']=exp($h['log_s']);$h['v']=$h['s_rel']/$total;}unset($h);usort($hasilHitung,fn($a,$b)=>$b['v']<=>$a['v']);
   try{$pdo->beginTransaction();$stmt=$pdo->prepare("INSERT INTO simulasi (nama_simulasi,keterangan,periode,metode,total_bobot_input,total_bobot_normalisasi,jumlah_alternatif,jumlah_kriteria,status,source_ahp_id,nama_acuan) VALUES (?,?,?,'AHP-WP',1,1,?,?,'draft',?,?)");$stmt->execute(['WP - '.$selected['nama_acuan'],'Bobot AHP dari: '.$selected['nama_simulasi'],$selected['periode'],count($hasilHitung),count($weights),$ahpId,$selected['nama_acuan']]);$sid=(int)$pdo->lastInsertId();$ih=$pdo->prepare('INSERT INTO hasil_spk (id_simulasi,id_alternatif,kode_alternatif,nama_alternatif,nilai_s,nilai_v,peringkat) VALUES (?,?,?,?,?,?,?)');$idetail=$pdo->prepare('INSERT INTO detail_hasil_spk (id_hasil,kode_kriteria,nama_kriteria,tipe_kriteria,bobot_input,bobot_normalisasi,nilai_alternatif,nilai_pangkat) VALUES (?,?,?,?,?,?,?,?)');foreach($hasilHitung as $rank=>$h){$a=$h['alternatif'];$ih->execute([$sid,$a['id_alternatif'],$a['kode'],$a['nama'],$h['s'],$h['v'],$rank+1]);$hid=(int)$pdo->lastInsertId();foreach($h['kontribusi'] as $c){$k=$c['kriteria'];$idetail->execute([$hid,$k['kode_kriteria'],$k['nama_kriteria'],$k['tipe_kriteria'],$c['bobot'],$c['bobot'],$c['nilai'],$c['kontribusi']]);}}$pdo->prepare("UPDATE simulasi SET status='selesai' WHERE id_simulasi=?")->execute([$sid]);$pdo->commit();header('Location: hasil.php?id='.$sid);exit;}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();error_log('[SPK WP] Gagal menyimpan hasil WP: '.$e->getMessage());$errors[]='WP gagal disimpan. Detail teknis dicatat di log PHP; periksa migrasi dan struktur tabel.';}
  }}
}
}
function fmtwp($v,$d=6){return number_format((float)$v,$d,',','.');}
?>
<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Perhitungan WP | SPK</title><link rel="stylesheet" href="../assets/css/style.css"><style>.subtle{color:#707b97;font-size:.9rem}.pick{display:flex;align-items:flex-start;gap:10px;padding:12px;border:1px solid #e0e4ef;border-radius:10px;margin:8px 0}.pick input{margin-top:5px}</style></head><body><header class="topbar"><a class="brand" href="../index.php">SPK <span>AHP–WP</span></a><nav><a href="../index.php">Dashboard</a><a href="../alternatif/index.php">Alternatif</a><a href="index.php">Perhitungan AHP</a><a class="active" href="wp.php">Perhitungan WP</a><a href="riwayat.php">Riwayat</a></nav></header><main class="container"><div class="page-heading"><div><p class="eyebrow">TAHAP 2 DARI 2</p><h1>Perhitungan WP</h1><p>Panggil hasil AHP tersimpan berdasarkan nama alternatif acuan, lalu pilih alternatif yang akan dibandingkan.</p></div></div><div class="workflow"><span>01 AHP tersimpan</span><span>02 Pilih nama acuan AHP</span><span>03 Pilih alternatif</span><span>04 Hasil WP</span></div><?php if($errors):?><div class="alert error"><ul><?php foreach(array_unique($errors) as $er):?><li><?=e($er)?></li><?php endforeach;?></ul></div><?php endif;?>
<section class="panel"><h2>1. Panggil hasil AHP</h2><form method="get" action="wp.php"><div class="form-group"><label>Hasil AHP / nama alternatif acuan *</label><select name="ahp_id" required><option value="">-- Pilih hasil AHP berdasarkan nama alternatif --</option><?php foreach($ahps as $a):?><option value="<?=(int)$a['id_simulasi']?>" <?=((int)$a['id_simulasi']===$ahpId?'selected':'')?>><?=e($a['nama_acuan']?:$a['nama_simulasi'])?> · <?=e($a['nama_simulasi'])?> · <?=!empty($a['periode'])?e(date('d-m-Y',strtotime($a['periode']))):'tanpa periode'?> (CR <?=fmtwp($a['cr'],4)?>)</option><?php endforeach;?></select></div><button class="button" type="submit">Panggil Bobot AHP</button><a class="button button-light" href="index.php">Hitung AHP Baru</a></form><?php if(!$ahps):?><p class="notice">Belum ada hasil AHP konsisten yang tersimpan. Selesaikan perhitungan AHP terlebih dahulu.</p><?php endif;?></section>
<?php if($selected):?><section class="panel"><h2>2. Bobot AHP yang dipanggil</h2><p class="notice">Acuan: <strong><?=e($selected['nama_acuan']?:$selected['nama_simulasi'])?></strong> · Periode: <strong><?=!empty($selected['periode'])?e(date('d-m-Y',strtotime($selected['periode']))):'—'?></strong> · CR: <strong><?=fmtwp($selected['cr'],5)?></strong></p><div class="table-wrap"><table><thead><tr><th>Kode</th><th>Kriteria</th><th>Atribut</th><th>Bobot AHP</th></tr></thead><tbody><?php foreach($weights as $w):?><tr><td><?=e($w['kode_kriteria'])?></td><td><?=e($w['nama_kriteria'])?></td><td><?=strtoupper(e($w['tipe_kriteria']))?></td><td><?=fmtwp($w['bobot'],8)?></td></tr><?php endforeach;?></tbody></table></div></section>
<form method="post" action="wp.php"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="ahp_id" value="<?=$ahpId?>"><input type="hidden" name="periode" value="<?=e($selected['periode']?:$periode)?>"><section class="panel"><h2>3. Pilih alternatif untuk dihitung</h2><p class="subtle">Alternatif otomatis mengikuti periode dari hasil AHP terpilih. Pilih minimal dua alternatif untuk membuat peringkat.</p><?php if(!$alternatif):?><p class="result-bad">Tidak ada alternatif pada periode ini.</p><?php else:foreach($alternatif as $a):?><label class="pick"><input type="checkbox" name="alternatif_ids[]" value="<?=(int)$a['id_alternatif']?>" <?=in_array((int)$a['id_alternatif'],array_map('intval',(array)($_POST['alternatif_ids']??[])),true)?'checked':''?>><span><strong><?=e($a['nama'])?></strong><br><small><?=e($a['kode'])?> · Periode <?=e(date('d-m-Y',strtotime($a['periode'])))?></small></span></label><?php endforeach;?><button class="button" type="submit">Hitung WP dengan Bobot AHP Terpilih →</button><?php endif;?></section></form><?php endif;?>
